WITH b AS (SELECT 'Nokia' AS co, family_id, publication_number, cpc_codes FROM nokia_analytics.portfolio_30y WHERE country_code = 'US' AND grant_date > 0 AND filing_date >= 20061101 AND STARTS_WITH(kind_code, 'B') UNION ALL SELECT CASE WHEN REGEXP_CONTAINS(UPPER(ARRAY_TO_STRING(owners, ' ')), r'CIENA') THEN 'Ciena' WHEN REGEXP_CONTAINS(UPPER(ARRAY_TO_STRING(owners, ' ')), r'CISCO|ACACIA|LUXTERA') THEN 'Cisco' WHEN REGEXP_CONTAINS(UPPER(ARRAY_TO_STRING(owners, ' ')), r'ARISTA') THEN 'Arista' ELSE 'Huawei' END, family_id, publication_number, cpc_codes FROM nokia_analytics.rivals_30y WHERE country_code = 'US' AND grant_date > 0 AND filing_date >= 20061101 AND STARTS_WITH(kind_code, 'B')), l AS (SELECT co, family_id, MIN(publication_number) AS pub FROM b WHERE EXISTS (SELECT 1 FROM UNNEST(cpc_codes) AS c WHERE STARTS_WITH(c, 'H04L49/')) GROUP BY co, family_id), r AS (SELECT *, COUNT(*) OVER (PARTITION BY co) AS pool_size, ROW_NUMBER() OVER (PARTITION BY co ORDER BY FARM_FINGERPRINT(CONCAT('codebook-2026', family_id))) AS rn FROM l) SELECT co, ANY_VALUE(pool_size) AS pool_size, STRING_AGG(pub, ' ' ORDER BY rn) AS sample FROM r WHERE rn <= CASE co WHEN 'Nokia' THEN 60 ELSE 30 END GROUP BY co ORDER BY co;
